<?php require __DIR__.'/bootstrap.php'; require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){ require_admin(); verify_csrf(); if(!isset($_FILES['file']) || $_FILES['file']['error']!==UPLOAD_ERR_OK) exit('Choose a valid file.'); $allowed=['application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document','image/png','image/jpeg']; if(!in_array(mime_content_type($_FILES['file']['tmp_name']),$allowed,true) || $_FILES['file']['size']>10*1024*1024) exit('Only PDF, DOCX, PNG or JPG files up to 10 MB are allowed.'); $dir=__DIR__.'/uploads'; if(!is_dir($dir)) mkdir($dir,0755,true); $stored=bin2hex(random_bytes(16)).'.'.pathinfo($_FILES['file']['name'],PATHINFO_EXTENSION); move_uploaded_file($_FILES['file']['tmp_name'],$dir.'/'.$stored); $s=$pdo->prepare('INSERT INTO resources(title,description,course,file_path,original_name,uploaded_by) VALUES(?,?,?,?,?,?)'); $s->execute([trim($_POST['title']),trim($_POST['description']),trim($_POST['course']),$stored,basename($_FILES['file']['name']),user()['id']]); log_action($pdo,'resource_uploaded',$stored); header('Location:resources.php'); exit; }
$rows=$pdo->query('SELECT r.*,u.name author FROM resources r JOIN users u ON u.id=r.uploaded_by ORDER BY r.created_at DESC')->fetchAll(); page_top('Resources'); ?><h1>Course resources</h1><?php if(user()['role']==='admin'): ?><details class="panel"><summary>Upload a resource</summary><form class="form-grid" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Title<input required name="title"></label><label>Course<input name="course"></label><label class="full">Description<textarea name="description"></textarea></label><label class="full">File<input required type="file" name="file" accept=".pdf,.docx,.png,.jpg,.jpeg"></label><button>Upload</button></form></details><?php endif; ?><section class="grid three"><?php foreach($rows as $r): ?><article class="panel"><h2><?=e($r['title'])?></h2><p><?=e($r['description'])?></p><small><?=e($r['course'])?> · <?=e($r['author'])?></small><p><a class="button" href="download.php?id=<?=$r['id']?>">Download</a></p></article><?php endforeach; ?></section><?php page_bottom();
